+const MODES = ['uppercase', 'lowercase', 'slug'];
+
+const TEXT_TRANSFORM_SCHEMA = {
+  type: 'object',
+  properties: {
+    text: { type: 'string', description: 'The text to transform.' },
+    mode: {
+      type: 'string',
+      enum: MODES,
+      description: 'Transform mode: uppercase, lowercase, or slug.'
+    },
+    trim: {
+      type: 'boolean',
+      default: true,
+      description: 'Trim surrounding whitespace before transforming. Defaults to true.'
+    }
+  },
+  required: ['text', 'mode'],
+  additionalProperties: false
+};
+
+export async function listTools() {
+  return [
+    {
+      name: 'text_transform',
+      description: 'Transform text to uppercase, lowercase, or a URL-safe slug.',
+      inputSchema: TEXT_TRANSFORM_SCHEMA
+    }
+  ];
+}
+
+function fail(message) {
+  throw new Error(message);
+}
+
+function validateArguments(args) {
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    fail('Arguments must be an object');
+  }
+  const allowed = new Set(['text', 'mode', 'trim']);
+  for (const key of Object.keys(args)) {
+    if (!allowed.has(key)) {
+      fail(`Unknown argument: ${key}`);
+    }
+  }
+  if (!('text' in args)) {
+    fail('Missing required argument: text');
+  }
+  if (!('mode' in args)) {
+    fail('Missing required argument: mode');
+  }
+  if (typeof args.text !== 'string') {
+    fail('Argument "text" must be a string');
+  }
+  if (typeof args.mode !== 'string' || !MODES.includes(args.mode)) {
+    fail('Argument "mode" must be one of: uppercase, lowercase, slug');
+  }
+  if ('trim' in args && typeof args.trim !== 'boolean') {
+    fail('Argument "trim" must be a boolean');
+  }
+}
+
+function toSlug(text) {
+  return text
+    .toLowerCase()
+    .replace(/[^a-z0-9]+/g, '-')
+    .replace(/^-+|-+$/g, '');
+}
+
+function transform(text, mode, trim) {
+  let result = text;
+  if (trim) {
+    result = result.trim();
+  }
+  switch (mode) {
+    case 'uppercase':
+      return result.toUpperCase();
+    case 'lowercase':
+      return result.toLowerCase();
+    case 'slug':
+      return toSlug(result);
+    default:
+      fail(`Unsupported mode: ${mode}`);
+  }
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'text_transform') {
+    fail(`Unknown tool: ${name}`);
+  }
+  validateArguments(args);
+  const trim = 'trim' in args ? args.trim : true;
+  const output = transform(args.text, args.mode, trim);
+  return {
+    content: [{ type: 'text', text: output }]
+  };
+}
